"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

export type RadialBurstAction = {
  id: string;
  label: string;
  onSelect?: () => void;
};

export type RadialBurstProps = {
  actions: RadialBurstAction[];
  className?: string;
  label?: string;
};

/**
 * Press-and-hold / click radial burst menu — actions fan out around the hub.
 */
function RadialBurst({
  actions,
  className,
  label = "Actions",
}: RadialBurstProps) {
  const [open, setOpen] = React.useState(false);
  const items = actions.slice(0, 6);

  return (
    <div className={cn("relative grid place-items-center py-10", className)}>
      {items.map((action, i) => {
        const angle = (-90 + (360 / items.length) * i) * (Math.PI / 180);
        const r = open ? 78 : 0;
        const x = Math.cos(angle) * r;
        const y = Math.sin(angle) * r;
        return (
          <button
            key={action.id}
            type="button"
            onClick={() => {
              action.onSelect?.();
              setOpen(false);
            }}
            className={cn(
              "absolute z-[1] rounded-full border border-border bg-card px-3 py-1.5 text-xs font-medium shadow-[var(--shadow-lift)] transition-all duration-300",
              open ? "opacity-100 scale-100" : "opacity-0 scale-50 pointer-events-none",
            )}
            style={{ transform: `translate(${x}px, ${y}px)` }}
          >
            {action.label}
          </button>
        );
      })}
      <button
        type="button"
        aria-expanded={open}
        onClick={() => setOpen((v) => !v)}
        className="relative z-[2] inline-flex h-14 w-14 items-center justify-center rounded-full bg-foreground text-xs font-semibold text-background shadow-[var(--shadow-lift)] transition-transform active:scale-95"
      >
        {open ? "Close" : label}
      </button>
    </div>
  );
}

export { RadialBurst };
